describe("Cart — async checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500, 10_000),
      region: "US",
    });
    cart.add(widget, 2); // subtotal = 2000
    cart.add(gadget, 1); // subtotal += 2000 → 4000
  });

  it("checkout without collaborators returns sync totals", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4_000);
    expect(result.totals.discountCents).toBe(400); // 10% of 4000
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1_500) // w1 now 1500
        .mockResolvedValueOnce(2_500), // g1 now 2500
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    // new subtotal = 1500*2 + 2500*1 = 5500
    expect(result.totals.subtotalCents).toBe(5_500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    expect(result.lines[1]!.product.unitPriceCents).toBe(2_500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.requested).toBe(2);
      expect(err.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1, // requested 2, only 1 available
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.available).toBe(1);
    }
  });

  it("passes when inventory is sufficient", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(4_000);
    expect(checker.check).toHaveBeenCalledTimes(2);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=4000, discount=400, discounted=3600
    // tax = floor(3600 * 0.08) = 288
    expect(result.totals.taxCents).toBe(288);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1_000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });
    // All prices refreshed to 1000: subtotal = 1000*2 + 1000*1 = 3000
    // discount 10% of 3000 = 300, discounted = 2700
    // tax = floor(2700 * 0.1) = 270
    // shipping: discounted(2700) < freeOver(10000) → flat 500
    expect(result.totals.subtotalCents).toBe(3_000);
    expect(result.totals.discountCents).toBe(300);
    expect(result.totals.taxCents).toBe(270);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2_700 + 270 + 500);
  });

  it("asyncTaxProvider failure propagates", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("priceFetcher failure propagates", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("inventory check passes with available:true and no availableQuantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(4_000);
  });

  it("checkout on empty cart returns zero totals", async () => {
    const emptyCart = new Cart();
    const result = await emptyCart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 → 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10_000)).toBe(1_000);
    });

    it("rounds down to nearest cent (10% of 1001 → 100)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1_001)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% returns entire subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5_000)).toBe(5_000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5_000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(15_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

