const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1_000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2_000 };
const heavy: Product = {
  id: "h1",
  name: "Heavy",
  unitPriceCents: 500,
  weightGrams: 2_000,
};

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts with 0 items and zero totals", () => {
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("adds a product and updates itemCount", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5_000);
  });

  it("throws on non-positive quantity", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("throws on negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w1", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot returns deep copies (mutations do not affect cart)", () => {
    cart.add(widget, 2);
    const snap = cart.snapshot();
    (snap[0] as CartLine).quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 3); // 6000
