    cart.add(gadget, 1); // subtotal += 2000 → 4000
  });

  it("checkout without collaborators returns sync totals", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4_000);
    expect(result.totals.discountCents).toBe(400); // 10% of 4000
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1_500) // w1 now 1500
        .mockResolvedValueOnce(2_500), // g1 now 2500
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    // new subtotal = 1500*2 + 2500*1 = 5500
    expect(result.totals.subtotalCents).toBe(5_500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    expect(result.lines[1]!.product.unitPriceCents).toBe(2_500);
