describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(10_000)).toBe(1_200);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(10_000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, which is fine; but if a custom policy
      // returned a negative, CompositeDiscountPolicy does Math.max(0, ...).
      const noDiscount = new NoDiscountPolicy();
      const fixed = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([noDiscount, fixed], "sum");
      expect(composite.computeDiscountCents(1_000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // subtotal = 10000
      // p1: 10% of 10000 = 1000 → remaining 9000
      // p2: fixed 200, min(200, 9000) = 200 → remaining 8800
      // total discount = 1200
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10_000)).toBe(1_200);
    });

    it("order matters: fixed then percentage differs from percentage then fixed", () => {
      // fixed 200 first: remaining = 10000 - 200 = 9800
      // then 10% of 9800 = 980 → total = 1180
      const fixedFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // percentage 10% first: remaining = 10000 - 1000 = 9000
      // then fixed 200 of 9000 = 200 → total = 1200
      const pctFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      expect(fixedFirst.computeDiscountCents(10_000)).toBe(1_180);
      expect(pctFirst.computeDiscountCents(10_000)).toBe(1_200);
    });

    it("stops discounting when remaining reaches 0", () => {
      // Two 100% discounts in chain: first takes everything, second gets 0 remaining
      const p1 = new PercentageDiscountPolicy(100);
      const p2 = new PercentageDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(5_000)).toBe(5_000);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
