toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1_000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5_000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 10_000)).toBe(0);
    });

    it("returns flatCents for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5_000)).toBe(799);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5_000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6_000)).toBe(0);
    });

    it("returns flatCents when subtotal is below free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4_999)).toBe(500);
    });

    it("returns 0 when freeOverCents is 0 and subtotal is 0", () => {
      const calc = new FlatShippingCalculator(500, 0);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 10.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1_000, costCents: 600 },
      { upToGrams: 5_000, costCents: 1_200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 10_000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 10_000),
      ).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 2 = 400g → first bracket (≤500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 200, 2)], 10_000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g exactly → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 10_000),
      ).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket (≤1000g) → 600
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 10_000),
      ).toBe(600);
    });

    it("selects heaviest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 5000g → third bracket
      expect(
        calc.computeShippingCents([makeLine("a", 5_000, 1)], 10_000),
      ).toBe(1_200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2_000);
      // 5001g → overflow → 2000
      expect(
        calc.computeShippingCents([makeLine("a", 5_001, 1)], 10_000),
      ).toBe(2_000);
    });

    it("defaults to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 10000g → no overflow → last bracket cost = 1200
      expect(
        calc.computeShippingCents([makeLine("a", 10_000, 1)], 10_000),
      ).toBe(1_200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5_000, costCents: 1_200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1_000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      // 400g → should match 500g bracket → 300
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 10_000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300*1 + 400*1 = 700g → second bracket → 600
      const lines = [makeLine("a", 300, 1), makeLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 10_000)).toBe(600);
    });
  });
});

