import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1_000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2_000 };
const heavy: Product = {
  id: "h1",
  name: "Heavy",
  unitPriceCents: 500,
  weightGrams: 2_000,
};

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts with 0 items and zero totals", () => {
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("adds a product and updates itemCount", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5_000);
  });

  it("throws on non-positive quantity", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("throws on negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w1", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nope", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot returns deep copies (mutations do not affect cart)", () => {
    cart.add(widget, 2);
    const snap = cart.snapshot();
    (snap[0] as CartLine).quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 3); // 6000
    expect(cart.totals().subtotalCents).toBe(8_000);
  });

  it("applies discount policy to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 5); // subtotal=5000
    const t = cart.totals();
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(5_000);
    expect(t.discountCents).toBe(500);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returns more than subtotal
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99_999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1_000);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(400),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1_000),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      region: "US-CA",
    });
    cart.add(widget, 5); // subtotal = 5000, discount = 1000, discounted = 4000
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4_000, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(800),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(widget, 3); // subtotal=3000, discount=500, discounted=2500
    const t = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2_500,
    );
    expect(t.shippingCents).toBe(800);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 200 },
      taxCalculator: { computeTaxCents: () => 150 },
      shippingCalculator: { computeShippingCents: () => 300 },
    });
    cart.add(widget, 1); // subtotal=1000, discount=200, discounted=800
    const t = cart.totals();
    // total = 800 + 150 + 300 = 1250
    expect(t.totalCents).toBe(1_250);
  });

  it("uses default collaborators (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(widget, 2); // subtotal=2000
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(2_000);
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1_000, "US");
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart — end-to-end with real policies", () => {
  it("10% discount + 8.75% regional tax + flat $5 shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US-CA": 0.0875 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US-CA",
    });
    cart.add(widget, 10); // subtotal = 10000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10_000);
    expect(t.discountCents).toBe(1_000); // 10% of 10000
    // tax = floor(9000 * 0.0875) = floor(787.5) = 787
    expect(t.taxCents).toBe(787);
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(9_000 + 787 + 500);
  });

  it("fixed $20 discount capped at subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2_000),
    });
    cart.add(widget, 1); // subtotal = 1000, discount capped at 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1_000);
    expect(t.totalCents).toBe(0);
  });
});

describe("Cart — async checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500, 10_000),
      region: "US",
    });
    cart.add(widget, 2); // subtotal = 2000
    cart.add(gadget, 1); // subtotal += 2000 → 4000
  });

  it("checkout without collaborators returns sync totals", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4_000);
    expect(result.totals.discountCents).toBe(400); // 10% of 4000
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1_500) // w1 now 1500
        .mockResolvedValueOnce(2_500), // g1 now 2500
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    // new subtotal = 1500*2 + 2500*1 = 5500
    expect(result.totals.subtotalCents).toBe(5_500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    expect(result.lines[1]!.product.unitPriceCents).toBe(2_500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.requested).toBe(2);
      expect(err.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1, // requested 2, only 1 available
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.available).toBe(1);
    }
  });

  it("passes when inventory is sufficient", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(4_000);
    expect(checker.check).toHaveBeenCalledTimes(2);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=4000, discount=400, discounted=3600
    // tax = floor(3600 * 0.08) = 288
    expect(result.totals.taxCents).toBe(288);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1_000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });
    // All prices refreshed to 1000: subtotal = 1000*2 + 1000*1 = 3000
    // discount 10% of 3000 = 300, discounted = 2700
    // tax = floor(2700 * 0.1) = 270
    // shipping: discounted(2700) < freeOver(10000) → flat 500
    expect(result.totals.subtotalCents).toBe(3_000);
    expect(result.totals.discountCents).toBe(300);
    expect(result.totals.taxCents).toBe(270);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2_700 + 270 + 500);
  });

  it("asyncTaxProvider failure propagates", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("priceFetcher failure propagates", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price API down",
    );
  });

  it("inventory check passes with available:true and no availableQuantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(4_000);
  });

  it("checkout on empty cart returns zero totals", async () => {
    const emptyCart = new Cart();
    const result = await emptyCart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

